CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_SUBSTATION_LOAD_DAY_REGION
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_SUBSTATION_LOAD at grain Date.FiscalYear, Date.FullDate, Date.IsHoliday, Date.MonthName, Date.Quarter, Location.Region, Date.MonthNumber; covers 55.45% of weighted demand (2 clusters); est. 11,000 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.FULL_DATE,
       d1.IS_HOLIDAY,
       d1.MONTH_NAME,
       d1.QUARTER,
       l2.REGION,
       d1.MONTH_NUMBER,
       SUM(f.LOAD_FACTOR_PCT) AS LOAD_FACTOR_PCT_SUM,
       COUNT(f.LOAD_FACTOR_PCT) AS LOAD_FACTOR_PCT_COUNT,
       MAX(f.PEAK_LOAD_MW) AS PEAK_LOAD_MW,
       COUNT(*) AS SUBSTATION_LOAD_COUNT
FROM CORE.FCT_SUBSTATION_LOAD f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_LOCATION l2 ON f.LOCATION_ID = l2.LOCATION_ID
GROUP BY ALL;

-- Dynamic tables refresh with the owner's privileges: re-apply source policies on the aggregate.
ALTER DYNAMIC TABLE AGG.AGG_SUBSTATION_LOAD_DAY_REGION ADD ROW ACCESS POLICY SEC.RAP_REGION ON (REGION);
